CREATE TABLE product (sku text PRIMARY KEY, price numeric(8,2));
INSERT INTO product VALUES ('A1', 1.50), ('B2', 4.00);
CREATE TABLE incoming (seq int, sku text, price numeric(8,2));
INSERT INTO incoming VALUES (1, 'A1', 1.60), (2, 'A1', 1.75), (3, 'C3', 2.20), (4, 'C3', 2.10), (5, 'B2', 4.00);
INSERT INTO product (sku, price)
SELECT DISTINCT ON (sku) sku, price FROM incoming ORDER BY sku, seq DESC
ON CONFLICT (sku) DO UPDATE SET price = EXCLUDED.price;
SELECT sku, price FROM product ORDER BY sku;
